#!/bin/bash
set -euo pipefail

THRESHOLD="${THRESHOLD:-80}"

df -hP | awk -v threshold="$THRESHOLD" '
NR > 1 {
    usage=$5
    gsub("%", "", usage)
    if (usage >= threshold)
        printf "WARNING: %s is %s%% full\n", $6, usage
    else
        printf "OK: %s is %s%% full\n", $6, usage
}'
